/**
 * The raw, typed Management API client (an openapi-fetch client).
 */
export type ApiClient = ManagementApiClient

/**
 * A single project as returned by the Management API.
 */
export type Project =
  operations['getV1Projects']['responses']['200']['content']['application/json']['data'][number]

/**
 * A single database as returned by the Management API.
 */
export type Database =
  operations['getV1ProjectsByProjectIdDatabases']['responses']['200']['content']['application/json']['data'][number]

/**
 * The result of creating a dev connection: the connection string to write to `.env`.
 */
export interface ConnectionResult {
  connectionString: string
}

type NormalizedError = {
  code?: string
  message: string
}

/**
 * Normalizes both API error response bodies (`{ error: { code, message } }`) and
 * thrown `Error` instances into a common shape.
 */
function normalizeError(raw: unknown): NormalizedError {
  if (raw && typeof raw === 'object') {
    const asRecord = raw as Record<string, any>

    // API error response body shape: { error: { code, message, hint } }
    if (asRecord.error && typeof asRecord.error === 'object') {
      return {
        code: asRecord.error.code,
        message: typeof asRecord.error.message === 'string' ? asRecord.error.message : 'Unknown error',
      }
    }

    // Thrown Error / plain object shape: { code?, message }
    if (typeof asRecord.message === 'string') {
      return { code: asRecord.code, message: asRecord.message }
    }
  }

  return { message: typeof raw === 'string' ? raw : 'Unknown error' }
}

function isAuthenticationError({ code, message }: NormalizedError): boolean {
  const c = (code ?? '').toString().toLowerCase()
  if (c.includes('auth') || c === 'unauthorized' || c === 'forbidden' || c === 'invalid_credentials') {
    return true
  }
  return /invalid credentials|unauthorized|authentication failed/i.test(message)
}

function isNotFoundError({ code, message }: NormalizedError): boolean {
  const c = (code ?? '').toString().toLowerCase()
  if (c.includes('not_found') || c.includes('notfound') || c === 'not-found') {
    return true
  }
  return /not found/i.test(message)
}

/**
 * Throws an `Error` classified from an API error body or a thrown error.
 * - Authentication failures throw with a message matching /Invalid credentials/.
 * - Not-found failures throw with a message matching /not found/.
 * - Everything else throws with the original API error message.
 */
function throwApiError(raw: unknown): never {
  const normalized = normalizeError(raw)

  if (isAuthenticationError(normalized)) {
    throw new Error('Invalid credentials')
  }

  if (isNotFoundError(normalized)) {
    throw new Error(/not found/i.test(normalized.message) ? normalized.message : `Database not found: ${normalized.message}`)
  }

  throw new Error(normalized.message)
}

/**
 * Removes sensitive data from error messages before they are surfaced to the user or logs.
 * - Replaces `postgres://` and `prisma+postgres://` connection strings with `[REDACTED_URL]`.
 * - Replaces `--api-key <value>` flag values with `--api-key [REDACTED]`.
 */
export function sanitizeErrorMessage(message: string): string {
  return message
    .replace(/(?:prisma\+postgres|postgres):\/\/\S+/gi, '[REDACTED_URL]')
    .replace(/--api-key[=\s]+\S+/gi, '--api-key [REDACTED]')
}

/**
 * Returns the list of projects the token has access to.
 * Throws with the API error message on failure.
 */
export async function listProjects(client: ApiClient): Promise<Project[]> {
  const { data, error } = await client.GET('/v1/projects', {})

  if (error) {
    throwApiError(error)
  }

  return data?.data ?? []
}

/**
 * Returns the databases for the given project.
 * Throws with the API error message on failure.
 */
export async function listDatabases(client: ApiClient, projectId: string): Promise<Database[]> {
  const { data, error } = await client.GET('/v1/projects/{projectId}/databases', {
    params: { path: { projectId } },
  })

  if (error) {
    throwApiError(error)
  }

  return data?.data ?? []
}

/**
 * Creates a dev connection for the given database and returns the connection string,
 * preferring the direct endpoint, then the pooled endpoint, then the deprecated
 * top-level connection string field.
 */
export async function createDevConnection(client: ApiClient, databaseId: string): Promise<ConnectionResult> {
  const { data, error } = await client.POST('/v1/databases/{databaseId}/connections', {
    params: { path: { databaseId } },
    body: { name: 'Prisma CLI' },
  })

  if (error) {
    throwApiError(error)
  }

  const connection = data?.data

  const connectionString =
    connection?.endpoints?.direct?.connectionString ??
    connection?.endpoints?.pooled?.connectionString ??
    connection?.connectionString

  if (!connectionString) {
    throw new Error('No connection string found in the Management API response')
  }

  return { connectionString }
}
