import path from 'node:path'

import dotenv from 'dotenv'

import type { ConnectionResult } from './management-api'

/**
 * Result of a `.env` upsert operation.
 */
export type EnvWriteResult = {
  created: boolean
  added: string[]
  updated: string[]
}

/**
 * Status of the `.gitignore` file with respect to a `.env` entry.
 */
export type GitignoreStatus = 'no-file' | 'ok' | 'missing-entry'

function escapeRegExp(value: string): string {
  return value.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')
}

/**
 * Creates or updates a `.env` file with the given key-value pairs.
 *
 * - If the file does not exist, it is created with all keys (`created: true`).
 * - Existing keys are updated in place, new keys are appended.
 * - Values are always written with single quotes to prevent variable expansion.
 *
 * The exact format written per line is `KEY='value'\n`.
 */
export function upsertEnvFile(envPath: string, vars: Record<string, string>): EnvWriteResult {
  const formatLine = (key: string, value: string) => `${key}='${value}'`

  if (!fs.existsSync(envPath)) {
    const content = Object.entries(vars)
      .map(([key, value]) => `${formatLine(key, value)}\n`)
      .join('')
    fs.writeFileSync(envPath, content)
    return { created: true, added: Object.keys(vars), updated: [] }
  }

  let content = fs.readFileSync(envPath, 'utf8')
  const added: string[] = []
  const updated: string[] = []

  for (const [key, value] of Object.entries(vars)) {
    const line = formatLine(key, value)
    const keyRegex = new RegExp(`^${escapeRegExp(key)}=.*$`, 'm')

    if (keyRegex.test(content)) {
      content = content.replace(keyRegex, line)
      updated.push(key)
    } else {
      if (content.length > 0 && !content.endsWith('\n')) {
        content += '\n'
      }
      content += `${line}\n`
      added.push(key)
    }
  }

  fs.writeFileSync(envPath, content)
  return { created: false, added, updated }
}

/**
 * Checks whether a `.gitignore` file exists in the given directory and whether it
 * includes an entry for `.env`.
 */
export function checkGitignore(dir: string): GitignoreStatus {
  const gitignorePath = path.join(dir, '.gitignore')

  if (!fs.existsSync(gitignorePath)) {
    return 'no-file'
  }

  const content = fs.readFileSync(gitignorePath, 'utf8')
  const entries = content.split(/\r?\n/).map((line) => line.trim())

  if (entries.includes('.env') || entries.includes('/.env')) {
    return 'ok'
  }

  return 'missing-entry'
}

/**
 * Writes the connection string from the given `ConnectionResult` to the `.env` file
 * in the specified directory as `DATABASE_URL`.
 */
export function writeLocalFiles(dir: string, connection: ConnectionResult): { env: EnvWriteResult } {
  const envPath = path.join(dir, '.env')
  const env = upsertEnvFile(envPath, { DATABASE_URL: connection.connectionString })
  return { env }
}

/**
 * Returns `true` if the `.env` file in the given directory contains a `DATABASE_URL`
 * pointing to a Prisma Postgres host (`db.prisma.io` or `db-pool.prisma.io`).
 */
export function isAlreadyLinked(dir: string): boolean {
  const envPath = path.join(dir, '.env')

  if (!fs.existsSync(envPath)) {
    return false
  }

  const parsed = dotenv.parse(fs.readFileSync(envPath, 'utf8'))
  const databaseUrl = parsed.DATABASE_URL

  if (!databaseUrl) {
    return false
  }

  return databaseUrl.includes('db.prisma.io') || databaseUrl.includes('db-pool.prisma.io')
}

/**
 * Formats a human-readable summary about the `.env` file operation.
 */
export function formatEnvSummary(opts: { env: EnvWriteResult; gitignoreStatus: GitignoreStatus }): string {
  const { env, gitignoreStatus } = opts

  let summary = env.created
    ? '  Created .env with connection strings'
    : '  Updated .env with connection strings'

  if (gitignoreStatus === 'missing-entry') {
    summary += '\n    warn Your .gitignore does not include .env — add it to avoid committing secrets'
  } else if (gitignoreStatus === 'no-file') {
    summary += '\n    warn No .gitignore found — create one and add .env to avoid committing secrets'
  }

  return summary
}
