import path from 'node:path'

import { select } from '@inquirer/prompts'
import type { PrismaConfigInternal } from '@prisma/config'
import { arg, Command, format, HelpError, isError } from '@prisma/internals'
import { createManagementApiClient } from '@prisma/management-api-sdk'
import { bold, dim, green, red } from 'kleur/colors'

import { login } from '../../management-api/auth'
import { createAuthenticatedManagementAPI } from '../../management-api/auth-client'
import { checkGitignore, formatEnvSummary, isAlreadyLinked, writeLocalFiles } from './local-setup'
import type { ApiClient } from './management-api'
import { createDevConnection, listDatabases, listProjects, sanitizeErrorMessage } from './management-api'

/**
 * The `utm_medium` used when starting a browser-based login from this command.
 */
const UTM_MEDIUM = 'command-postgres-link'

/**
 * Matches a Prisma Postgres database id, e.g. `db_abc123`.
 */
const DATABASE_ID_REGEX = /^db_[A-Za-z0-9]+$/

/**
 * $ prisma postgres link
 *
 * Links a local project to a Prisma Postgres database by writing the connection
 * string to the local `.env` file.
 */
export class Link implements Command {
  static new(): Link {
    return new Link()
  }

  private constructor() {}

  private static help = format(`
  Link a local project to a Prisma Postgres database

  ${bold('Usage')}

    ${dim('$')} prisma postgres link [options]

  ${bold('Options')}

    -h, --help       Display this help message
        --api-key    A Prisma Postgres API key for non-interactive linking
        --database   The Prisma Postgres database id (db_...) to link to
        --force      Re-link even if the project is already linked

  ${bold('Examples')}

  Link interactively (opens the browser to authenticate)
    ${dim('$')} prisma postgres link

  Link non-interactively using an API key and a database id
    ${dim('$')} prisma postgres link --api-key <key> --database db_xxxxxxxx
`)

  public help(error?: string): string | HelpError {
    if (error) {
      return new HelpError(`\n${bold(red(`!`))} ${error}\n${Link.help}`)
    }
    return Link.help
  }

  async parse(
    argv: string[],
    _config: PrismaConfigInternal,
    cwd: string = process.cwd(),
  ): Promise<string | HelpError | Error> {
    const args = arg(argv, {
      '--help': Boolean,
      '-h': '--help',
      '--api-key': String,
      '--database': String,
      '--force': Boolean,
    })

    if (isError(args)) {
      return this.help(args.message)
    }

    if (args['--help']) {
      return this.help()
    }

    const dir = cwd ?? process.cwd()
    const force = Boolean(args['--force'])

    const hasApiKeyFlag = args['--api-key'] !== undefined
    const hasDatabaseFlag = args['--database'] !== undefined
    const interactive = !hasApiKeyFlag && !hasDatabaseFlag

    // Skip everything if the project is already linked, unless the user forces a re-link.
    if (isAlreadyLinked(dir) && !force) {
      return `This project is already linked to a Prisma Postgres database (see ${green(
        'DATABASE_URL',
      )} in your ${green('.env')}).\nUse ${green('--force')} to re-link it to a different database.`
    }

    try {
      if (interactive) {
        return await this.linkInteractively(dir)
      }
      return await this.linkNonInteractively({ args, dir })
    } catch (e) {
      const message = e instanceof Error ? e.message : String(e)
      return this.help(sanitizeErrorMessage(message))
    }
  }

  /**
   * Non-interactive linking: uses an API key (from `--api-key` or `PRISMA_API_KEY`)
   * and a database id passed via `--database`.
   */
  private async linkNonInteractively({
    args,
    dir,
  }: {
    args: { '--api-key'?: string; '--database'?: string }
    dir: string
  }): Promise<string | HelpError | Error> {
    const database = args['--database']

    if (!database) {
      return this.help('The --database option is required when using --api-key.')
    }

    if (!DATABASE_ID_REGEX.test(database)) {
      return this.help(
        `The --database value "${database}" is not a valid Prisma Postgres database id. It must start with "db_".`,
      )
    }

    const apiKey = args['--api-key'] ?? process.env.PRISMA_API_KEY

    if (!apiKey) {
      return this.help(
        'An API key is required. Provide it via --api-key or set the PRISMA_API_KEY environment variable.',
      )
    }

    const client = createManagementApiClient({ token: apiKey })

    return this.finishLink({ client, databaseId: database, dir })
  }

  /**
   * Interactive linking: authenticates via the browser and lets the user pick a
   * project and a database.
   */
  private async linkInteractively(dir: string): Promise<string | HelpError | Error> {
    let client = createAuthenticatedManagementAPI().client

    let projects
    try {
      projects = await listProjects(client)
    } catch (e) {
      if (!this.isInvalidRefreshTokenError(e)) {
        throw e
      }
      // The stored refresh token is invalid: re-authenticate and retry.
      await login({ utmMedium: UTM_MEDIUM })
      client = createAuthenticatedManagementAPI().client
      projects = await listProjects(client)
    }

    if (projects.length === 0) {
      return new HelpError(
        `\n${bold(red(`!`))} No projects found. Create a project on the Prisma Data Platform first.`,
      )
    }

    const projectId = await select({
      message: 'Select a project:',
      choices: projects.map((project) => ({
        name: project.name,
        value: project.id,
      })),
    })

    const databases = await listDatabases(client, projectId)
    const readyDatabases = databases.filter((database) => database.status === 'ready')

    if (readyDatabases.length === 0) {
      return new HelpError(
        `\n${bold(red(`!`))} No ready databases found for the selected project.`,
      )
    }

    const databaseId =
      readyDatabases.length === 1
        ? readyDatabases[0].id
        : await select({
            message: 'Select a database:',
            choices: readyDatabases.map((database) => ({
              name: database.name,
              value: database.id,
            })),
